SELECT a.id AS activityId, a.activity_name AS activityName, ag.spec_id AS specId, ag.original_price AS originalPrice, ag.activity_price AS activityPrice, ag.activity_stock AS activityStock, ag.sold_count AS soldCount, ag.limit_per_user AS limitPerUser, a.start_time AS startTime, a.end_time AS endTime FROM mall_activity a INNER JOIN mall_activity_goods ag ON a.id = ag.activity_id WHERE ag.spec_id IN
#{id}
AND a.status IN (0, 1, 2) AND a.end_time > #{nowTime}

SELECT a.id AS activityId, a.activity_name AS activityName, ag.spec_id AS specId, ag.original_price AS originalPrice, ag.activity_price AS activityPrice, ag.activity_stock AS activityStock, ag.sold_count AS soldCount, ag.limit_per_user AS limitPerUser, a.start_time AS startTime, a.end_time AS endTime FROM mall_activity a INNER JOIN mall_activity_goods ag ON a.id = ag.activity_id WHERE ag.spec_id IN
#{id}
AND a.status != 3 AND a.start_time <= #{nowTime} AND a.end_time > #{nowTime}

SELECT a.id AS activityId, a.activity_name AS activityName, ag.spec_id AS specId, ag.original_price AS originalPrice, ag.activity_price AS activityPrice, ag.activity_stock AS activityStock, ag.sold_count AS soldCount, ag.limit_per_user AS limitPerUser, a.start_time AS startTime, a.end_time AS endTime FROM mall_activity a INNER JOIN mall_activity_goods ag ON a.id = ag.activity_id WHERE ag.spec_id IN
#{id}
AND a.status = 0 AND a.start_time > #{nowTime}
